    const keep = []; fp.scene.traverse((m) => { if (m.isMesh && m.visible && !m.isInstancedMesh && !/grass|living|walkers|inhabitants|terrain|sky|water|fog|cloud/i.test(m.name) && m.geometry?.boundingSphere) keep.push(m); });
